CREATE TABLE network_permissions (user_id TEXT PRIMARY KEY REFERENCES network_members(user_id), call_in INTEGER NOT NULL DEFAULT 1 CHECK(call_in IN (0,1)), call_out INTEGER NOT NULL DEFAULT 1 CHECK(call_out IN (0,1)), message_in INTEGER NOT NULL DEFAULT 1 CHECK(message_in IN (0,1)), message_out INTEGER NOT NULL DEFAULT 1 CHECK(message_out IN (0,1)), updated_at INTEGER NOT NULL, updated_by TEXT NOT NULL);
